-- J5 — VERIFICAÇÃO (somente leitura; só nomes e contagens). Esperado: buckets privados com limites; visitante sem escrita no Storage; função de leitura segura; arquivos intactos.
select 'buckets de comprovantes privados com limite e tipos (esperado 2)' as item, (select count(*) from storage.buckets where id in ('comprovantes', 'mercari-comprovantes') and not public and file_size_limit = 10485760 and allowed_mime_types is not null)::text as valor
union all select 'policies de escrita no Storage para o visitante (esperado 0)', (select count(*) from pg_policies p where p.schemaname = 'storage' and p.tablename = 'objects' and p.cmd in ('INSERT', 'UPDATE', 'DELETE', 'ALL') and 'anon' = any(p.roles))::text
union all select 'policies de INSERT específicas dos comprovantes (esperado 0)', (select count(*) from pg_policies where schemaname = 'storage' and tablename = 'objects' and policyname in ('anon upload comprovante', 'comprovantes upload', 'joiner upload comprovante'))::text
union all select 'comprovante_assinavel segura e fechada ao visitante (esperado true)', (select (p.prosecdef and p.proconfig = array['search_path=""'] and not has_function_privilege('anon', p.oid, 'EXECUTE'))::text from pg_proc p where p.oid = 'public.comprovante_assinavel(text,text)'::regprocedure)
union all select 'tabela de controle de envios fechada (esperado false)', (has_table_privilege('anon', 'public.comprovantes_uploads', 'SELECT') or has_table_privilege('authenticated', 'public.comprovantes_uploads', 'SELECT'))::text
union all select 'arquivos antes | agora (comprovantes)', coalesce((select detalhe from emergencia.c0b_estado_anterior where etapa = 'J5' and objeto = 'arquivos comprovantes'), 'sem registro') || ' | quantidade=' || (select count(*) from storage.objects where bucket_id = 'comprovantes')
union all select 'arquivos antes | agora (mercari-comprovantes)', coalesce((select detalhe from emergencia.c0b_estado_anterior where etapa = 'J5' and objeto = 'arquivos mercari-comprovantes'), 'sem registro') || ' | quantidade=' || (select count(*) from storage.objects where bucket_id = 'mercari-comprovantes')
union all select 'estado registrado (linhas J5, esperado >= 10)', (select count(*) from emergencia.c0b_estado_anterior where etapa = 'J5')::text;
